:root {
  --bg-primary: #0f0f1a;
  --bg-secondary: #1a1a2e;
  --bg-tertiary: #16213e;
  --bg-card: #1e1e32;
  --bg-hover: #252540;
  --border-color: #2a2a4a;
  --text-primary: #e8e8f0;
  --text-secondary: #9a9ab0;
  --text-muted: #6a6a80;
  --accent-blue: #2962ff;
  --accent-teal: #00bcd4;
  --gain-green: #26a69a;
  --loss-red: #f7525f;
  --badge-green-bg: rgba(38, 166, 154, 0.15);
  --badge-red-bg: rgba(247, 82, 95, 0.15);
  --gold: #ffd700;
  --platinum: #b0b0c0;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 14px; scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--accent-blue); text-decoration: none; transition: color 0.2s; }
a:hover { color: #5b8aff; }

img { max-width: 100%; display: block; }

.container { max-width: 1400px; margin: 0 auto; padding: 0 20px; }

/* Navigation */
.main-nav {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 100;
  padding: 0 20px;
}
.nav-inner {
  max-width: 1400px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  height: 52px;
  gap: 32px;
}
.nav-logo {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
}
.nav-logo .logo-icon {
  width: 28px;
  height: 28px;
  background: var(--accent-blue);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.85rem;
}
.nav-links { display: flex; gap: 4px; flex: 1; }
.nav-links a {
  color: var(--text-secondary);
  padding: 8px 14px;
  border-radius: 6px;
  font-size: 0.9rem;
  font-weight: 500;
  transition: all 0.2s;
}
.nav-links a:hover, .nav-links a.active {
  color: var(--text-primary);
  background: var(--bg-hover);
}
.nav-actions { display: flex; gap: 8px; align-items: center; }
.nav-search {
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 6px 12px;
  color: var(--text-secondary);
  font-size: 0.85rem;
  width: 200px;
  outline: none;
  transition: border-color 0.2s;
}
.nav-search:focus { border-color: var(--accent-blue); }
.nav-search::placeholder { color: var(--text-muted); }

/* Buttons */
.btn {
  padding: 8px 18px;
  border-radius: 6px;
  font-size: 0.85rem;
  font-weight: 600;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}
.btn-primary { background: var(--accent-blue); color: #fff; }
.btn-primary:hover { background: #1e50e0; }
.btn-secondary {
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--border-color);
}
.btn-secondary:hover { color: var(--text-primary); border-color: var(--text-secondary); }
.btn-ghost { background: transparent; color: var(--text-secondary); }
.btn-ghost:hover { color: var(--text-primary); background: var(--bg-hover); }
.btn-sm { padding: 5px 12px; font-size: 0.8rem; }

/* Change badges */
.change { font-weight: 600; font-size: 0.85rem; }
.change.positive { color: var(--gain-green); }
.change.negative { color: var(--loss-red); }
.change-badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 0.8rem;
  font-weight: 600;
}
.change-badge.positive { background: var(--badge-green-bg); color: var(--gain-green); }
.change-badge.negative { background: var(--badge-red-bg); color: var(--loss-red); }

/* Tabs */
.tabs {
  display: flex;
  gap: 2px;
  background: var(--bg-primary);
  border-radius: 8px;
  padding: 3px;
  border: 1px solid var(--border-color);
  width: fit-content;
}
.tab-btn {
  padding: 6px 16px;
  border: none;
  background: transparent;
  color: var(--text-secondary);
  font-size: 0.85rem;
  font-weight: 500;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s;
  white-space: nowrap;
}
.tab-btn:hover { color: var(--text-primary); }
.tab-btn.active { background: var(--accent-blue); color: #fff; }

.tab-pills { display: flex; gap: 8px; flex-wrap: wrap; }
.tab-pill {
  padding: 6px 16px;
  border: 1px solid var(--border-color);
  background: transparent;
  color: var(--text-secondary);
  font-size: 0.85rem;
  font-weight: 500;
  border-radius: 20px;
  cursor: pointer;
  transition: all 0.2s;
}
.tab-pill:hover { color: var(--text-primary); border-color: var(--text-primary); }
.tab-pill.active { background: var(--accent-blue); color: #fff; border-color: var(--accent-blue); }

/* Cards */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 10px;
  padding: 20px;
  transition: border-color 0.2s;
}
.card:hover { border-color: #3a3a5a; }

/* Tables */
.data-table { width: 100%; border-collapse: collapse; }
.data-table th {
  text-align: left;
  padding: 10px 12px;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-bottom: 1px solid var(--border-color);
}
.data-table td {
  padding: 10px 12px;
  font-size: 0.88rem;
  border-bottom: 1px solid rgba(42, 42, 74, 0.5);
}
.data-table tr:hover td { background: var(--bg-hover); }
.data-table .text-right { text-align: right; }
.data-table .ticker { font-weight: 600; color: var(--accent-blue); }

/* Sparkline */
.sparkline {
  width: 80px;
  height: 28px;
  display: inline-block;
  vertical-align: middle;
}

/* Section headers */
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}
.section-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-primary);
}
.section-subtitle {
  font-size: 0.88rem;
  color: var(--text-secondary);
}

/* Grid layouts */
.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.grid-3 { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 16px; }
.grid-4 { display: grid; grid-template-columns: 1fr 1fr 1fr 1fr; gap: 16px; }

/* Market bar */
.market-bar {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  overflow-x: auto;
  white-space: nowrap;
  padding: 8px 20px;
}
.market-bar-inner {
  max-width: 1400px;
  margin: 0 auto;
  display: flex;
  gap: 24px;
  align-items: center;
}
.market-bar-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.82rem;
}
.market-bar-item .name { color: var(--text-secondary); }
.market-bar-item .price { color: var(--text-primary); font-weight: 600; }

/* Footer */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  padding: 48px 20px 24px;
  margin-top: 60px;
}
.footer-inner {
  max-width: 1400px;
  margin: 0 auto;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 24px;
  margin-bottom: 32px;
}
.footer-col h4 {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.footer-col a {
  display: block;
  color: var(--text-secondary);
  font-size: 0.82rem;
  padding: 3px 0;
}
.footer-col a:hover { color: var(--text-primary); }
.footer-bottom {
  border-top: 1px solid var(--border-color);
  padding-top: 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* Tier badges */
.tier-badge {
  display: inline-block;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.tier-platinum { background: rgba(176, 176, 192, 0.15); color: var(--platinum); }
.tier-gold { background: rgba(255, 215, 0, 0.15); color: var(--gold); }

/* Rating stars */
.rating { display: flex; align-items: center; gap: 4px; }
.stars { color: var(--gold); letter-spacing: 1px; }
.rating-score { font-weight: 700; font-size: 1rem; }
.rating-label { font-size: 0.82rem; color: var(--text-secondary); }

/* Scrollbar */
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: var(--bg-primary); }
::-webkit-scrollbar-thumb { background: var(--border-color); border-radius: 4px; }
::-webkit-scrollbar-thumb:hover { background: #3a3a5a; }

/* Toggle switch */
.toggle-switch { position: relative; display: inline-block; width: 36px; height: 20px; }
.toggle-switch input { opacity: 0; width: 0; height: 0; }
.toggle-slider {
  position: absolute; cursor: pointer;
  top: 0; left: 0; right: 0; bottom: 0;
  background: var(--border-color);
  border-radius: 20px;
  transition: 0.3s;
}
.toggle-slider:before {
  content: "";
  position: absolute;
  height: 14px; width: 14px;
  left: 3px; bottom: 3px;
  background: var(--text-primary);
  border-radius: 50%;
  transition: 0.3s;
}
.toggle-switch input:checked + .toggle-slider { background: var(--accent-blue); }
.toggle-switch input:checked + .toggle-slider:before { transform: translateX(16px); }

/* Hero */
.hero {
  padding: 80px 20px;
  text-align: center;
  background: linear-gradient(180deg, var(--bg-secondary) 0%, var(--bg-primary) 100%);
}
.hero h1 {
  font-size: 2.8rem;
  font-weight: 800;
  line-height: 1.15;
  max-width: 700px;
  margin: 0 auto 16px;
  background: linear-gradient(135deg, #fff 0%, #b0b0d0 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.hero p {
  font-size: 1.1rem;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto 32px;
  line-height: 1.6;
}
.hero-actions { display: flex; gap: 12px; justify-content: center; }
.hero .btn-primary { padding: 12px 28px; font-size: 1rem; }
.hero .btn-secondary { padding: 12px 28px; font-size: 1rem; }

/* Stats banner */
.stats-banner {
  background: linear-gradient(135deg, var(--bg-tertiary) 0%, var(--bg-secondary) 100%);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 32px;
  display: flex;
  justify-content: space-around;
  align-items: center;
  margin: 40px 0;
}
.stat-item { text-align: center; }
.stat-value { font-size: 2rem; font-weight: 800; color: var(--text-primary); }
.stat-label { font-size: 0.88rem; color: var(--text-secondary); margin-top: 4px; }

/* Page section spacing */
.page-section { padding: 32px 0; }
.page-section + .page-section { padding-top: 0; }

/* Responsive */
@media (max-width: 1200px) {
  .grid-4 { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 900px) {
  .grid-3, .grid-2 { grid-template-columns: 1fr; }
  .hero h1 { font-size: 2rem; }
  .hero { padding: 48px 20px; }
  .stats-banner { flex-direction: column; gap: 20px; }
  .nav-search { display: none; }
}
@media (max-width: 600px) {
  .grid-4 { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .nav-links { display: none; }
  html { font-size: 13px; }
}

