:root {
  --bg-primary: #0f0f1a;
  --bg-secondary: #1a1a2e;
  --bg-tertiary: #16213e;
  --bg-card: #1e1e32;
  --bg-hover: #252540;
  --border-color: #2a2a4a;
  --text-primary: #e8e8f0;
  --text-secondary: #9a9ab0;
  --text-muted: #6a6a80;
  --accent-blue: #2962ff;
  --accent-teal: #00bcd4;
  --gain-green: #26a69a;
  --loss-red: #f7525f;
  --badge-green-bg: rgba(38, 166, 154, 0.15);
  --badge-red-bg: rgba(247, 82, 95, 0.15);
  --gold: #ffd700;
  --platinum: #b0b0c0;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 14px; scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--accent-blue); text-decoration: none; transition: color 0.2s; }
a:hover { color: #5b8aff; }

