.tab-btn {
  padding: 6px 16px;
  border: none;
  background: transparent;
  color: var(--text-secondary);
  font-size: 0.85rem;
  font-weight: 500;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s;
  white-space: nowrap;
}
.tab-btn:hover { color: var(--text-primary); }
.tab-btn.active { background: var(--accent-blue); color: #fff; }

.tab-pills { display: flex; gap: 8px; flex-wrap: wrap; }
.tab-pill {
  padding: 6px 16px;
  border: 1px solid var(--border-color);
  background: transparent;
  color: var(--text-secondary);
  font-size: 0.85rem;
  font-weight: 500;
  border-radius: 20px;
  cursor: pointer;
  transition: all 0.2s;
}
.tab-pill:hover { color: var(--text-primary); border-color: var(--text-primary); }
.tab-pill.active { background: var(--accent-blue); color: #fff; border-color: var(--accent-blue); }

