  white-space: nowrap;
  padding: 8px 20px;
}
.market-bar-inner {
  max-width: 1400px;
  margin: 0 auto;
  display: flex;
  gap: 24px;
  align-items: center;
}
.market-bar-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.82rem;
}
.market-bar-item .name { color: var(--text-secondary); }
