  if (!canvas) return;
  const rect = canvas.parentElement.getBoundingClientRect();
  const dpr = window.devicePixelRatio || 1;
  canvas.width = rect.width * dpr;
  canvas.height = rect.height * dpr;
  canvas.style.width = rect.width + 'px';
  canvas.style.height = rect.height + 'px';
  const ctx = canvas.getContext('2d');
  ctx.scale(dpr, dpr);
  const w = rect.width;
  const h = rect.height;

  const candles = generateCandles(80);
  const allPrices = candles.flatMap(c => [c.h, c.l]);
  const minP = Math.min(...allPrices);
  const maxP = Math.max(...allPrices);
  const range = maxP - minP;
  const padTop = 30, padBot = 40, padLeft = 10, padRight = 60;
  const chartW = w - padLeft - padRight;
  const chartH = h - padTop - padBot;
  const barW = chartW / candles.length;
  const bodyW = Math.max(barW * 0.6, 3);

  // Grid lines
  ctx.strokeStyle = '#1e1e32';
  ctx.lineWidth = 0.5;
  for (let i = 0; i <= 5; i++) {
    const y = padTop + (chartH / 5) * i;
    ctx.beginPath(); ctx.moveTo(padLeft, y); ctx.lineTo(w - padRight, y); ctx.stroke();
    const priceLabel = (maxP - (range / 5) * i).toFixed(2);
    ctx.fillStyle = '#6a6a80';
    ctx.font = '10px Inter, sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText(priceLabel, w - padRight + 6, y + 3);
  }

  // Volume bars
  const maxVol = Math.max(...candles.map(c => c.vol));
  const volH = 40;
  candles.forEach((c, i) => {
    const x = padLeft + i * barW + barW / 2;
    const vH = (c.vol / maxVol) * volH;
    ctx.fillStyle = c.c >= c.o ? 'rgba(38,166,154,0.25)' : 'rgba(247,82,95,0.25)';
    ctx.fillRect(x - bodyW / 2, h - padBot - vH, bodyW, vH);
  });

  // Candles
  candles.forEach((c, i) => {
    const x = padLeft + i * barW + barW / 2;
    const bullish = c.c >= c.o;
    const color = bullish ? '#26a69a' : '#f7525f';

    // Wick
    const yH = padTop + ((maxP - c.h) / range) * chartH;
    const yL = padTop + ((maxP - c.l) / range) * chartH;
    ctx.strokeStyle = color;
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(x, yH); ctx.lineTo(x, yL); ctx.stroke();

    // Body
    const yO = padTop + ((maxP - c.o) / range) * chartH;
    const yC = padTop + ((maxP - c.c) / range) * chartH;
    ctx.fillStyle = color;
    const bodyTop = Math.min(yO, yC);
    const bodyHeight = Math.max(Math.abs(yC - yO), 1);
    ctx.fillRect(x - bodyW / 2, bodyTop, bodyW, bodyHeight);
  });

  // Moving average line
  const maPeriod = 20;
  ctx.beginPath();
  ctx.strokeStyle = '#ffd700';
  ctx.lineWidth = 1.2;
  candles.forEach((_, i) => {
    if (i < maPeriod - 1) return;
    let sum = 0;
    for (let j = i - maPeriod + 1; j <= i; j++) sum += candles[j].c;
    const ma = sum / maPeriod;
    const x = padLeft + i * barW + barW / 2;
    const y = padTop + ((maxP - ma) / range) * chartH;
    if (i === maPeriod - 1) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  });
  ctx.stroke();

  // EMA line
  ctx.beginPath();
  ctx.strokeStyle = '#2962ff';
  ctx.lineWidth = 1.2;
  let ema = candles[0].c;
  const mult = 2 / (10 + 1);
  candles.forEach((c, i) => {
    ema = (c.c - ema) * mult + ema;
    const x = padLeft + i * barW + barW / 2;
    const y = padTop + ((maxP - ema) / range) * chartH;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  });
  ctx.stroke();

  // Legend
  ctx.font = '11px Inter, sans-serif';
  ctx.fillStyle = '#ffd700'; ctx.fillText('SMA(20)', padLeft + 8, padTop + 14);
  ctx.fillStyle = '#2962ff'; ctx.fillText('EMA(10)', padLeft + 76, padTop + 14);

  function generateCandles(count) {
    const data = [];
    let price = 260;
    for (let i = 0; i < count; i++) {
      const o = price + (Math.random() - 0.5) * 3;
      const c = o + (Math.random() - 0.48) * 5;
      const h = Math.max(o, c) + Math.random() * 3;
      const l = Math.min(o, c) - Math.random() * 3;
      const vol = 30 + Math.random() * 25;
      data.push({ o, h, l, c, vol });
      price = c;
    }
    return data;
  }
})();

